INSERT IGNORE INTO faqs (question,answer,sort_order) VALUES ('What\'s in your ice cream?','Fresh local milk and cream, real fruit, sugar and a little vanilla. That\'s the whole list — no artificial colours, flavours or preservatives.',0);
INSERT IGNORE INTO faqs (question,answer,sort_order) VALUES ('Do you have dairy-free options?','Our coconut flavour is made with real coconut milk and is naturally dairy-free. Let us know your needs when you order and we\'ll guide you through the options.',1);
INSERT IGNORE INTO faqs (question,answer,sort_order) VALUES ('Are your flavours suitable for vegetarians?','Yes, all ten flavours are vegetarian. We don\'t use gelatine or animal rennet.',2);
INSERT IGNORE INTO faqs (question,answer,sort_order) VALUES ('Do you deliver outside Morogoro?','We deliver across Morogoro town every day. For special event orders further afield, message us and we\'ll see what we can arrange.',3);
INSERT IGNORE INTO faqs (question,answer,sort_order) VALUES ('How long does ice cream keep?','Best enjoyed the day you get it. In a home freezer it keeps well for up to two weeks — just let it soften a few minutes before scooping.',4);
INSERT IGNORE INTO faqs (question,answer,sort_order) VALUES ('Can I order a party tub?','Absolutely. Our tubs come in 1-litre and 4-litre sizes, and you can mix flavours. WhatsApp us your date and guest count and we\'ll sort it out.',5);
INSERT IGNORE INTO faqs (question,answer,sort_order) VALUES ('Do you cater weddings and events?','We do! Scoop stations, party tubs and custom carts are all available. Head to the Events page or message us for a quote.',6);
INSERT IGNORE INTO faqs (question,answer,sort_order) VALUES ('Can I request a custom flavour?','For events we can often create a custom batch. Get in touch early and we\'ll talk through what you have in mind.',7);
INSERT IGNORE INTO faqs (question,answer,sort_order) VALUES ('How do I pay?','Payment is simple — pay on delivery or send it via mobile money. We\'ll confirm the details when you order.',8);
INSERT IGNORE INTO faqs (question,answer,sort_order) VALUES ('What are your opening hours?','Every day, 8:00 AM to 9:00 PM. Come by, or message us any time and we\'ll reply as soon as we can.',9);
INSERT IGNORE INTO testimonials (quote,author,location,flavour_tag) VALUES ('The ukwaju flavour tastes exactly like childhood. My kids ask for it every weekend!','Amina J.','Kihonda','Ukwaju');
INSERT IGNORE INTO testimonials (quote,author,location,flavour_tag) VALUES ('Creamy, fresh and you can taste the real mango. Best ice cream in Morogoro, hands down.','Daniel M.','Mazimbu','Mango');
INSERT IGNORE INTO testimonials (quote,author,location,flavour_tag) VALUES ('Ordered for my daughter\'s birthday and everyone loved it. Cookies & Cream disappeared first.','Neema K.','Boma Road','Cookies & Cream');
INSERT IGNORE INTO testimonials (quote,author,location,flavour_tag) VALUES ('Mint choc chip after a long hot day is pure heaven. Friendly service too.','Joseph L.','SUA Campus','Mint Choc Chip');
